typedef struct { long id; char name[64]; } customer;   /* domain type: no SQL, no driver */

static const char *SQL_FIND = "SELECT id, name FROM customers WHERE id = ?";

int customer_mapper_load(sqlite3 *db, long id, customer *out) {
    sqlite3_stmt *st;
    if (sqlite3_prepare_v2(db, SQL_FIND, -1, &st, NULL) != SQLITE_OK) return -1;
    sqlite3_bind_int64(st, 1, id);
    if (sqlite3_step(st) != SQLITE_ROW) { sqlite3_finalize(st); return -1; }
    out->id = sqlite3_column_int64(st, 0);
    snprintf(out->name, sizeof out->name, "%s", (const char *)sqlite3_column_text(st, 1));
    sqlite3_finalize(st);                          /* every prepare needs a finalize */
    return 0;
}
